1	{
2	  "$schema": "https://json-schema.org/draft/2020-12/schema",
3	  "title": "investigation answer v2",
4	  "type": "object",
5	  "additionalProperties": false,
6	  "required": ["schema_version", "mechanism", "protocol", "findings", "timeline", "confidence"],
7	  "$defs": {
8	    "iso": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}(:[0-9]{2})?(Z|[+-][0-9]{2}:[0-9]{2})?$"},
9	    "id": {"type": "string", "pattern": "^[a-z_]+:[A-Za-z0-9_.@/:-]+$"},
10	    "zone": {"type": "string", "pattern": "^[A-Z]$"},
11	    "conf": {"type": "number", "minimum": 0, "maximum": 1},
12	    "hex8": {"type": "string", "pattern": "^[0-9A-Fa-f]{2}$"},
13	    "ACTIONS": {"enum": ["door_prop", "door_open", "door_close", "pallet_move", "firmware_flash", "config_edit", "commit", "override_deploy", "archive_channel", "probe_check", "ticket_open", "ticket_close", "alert_ack", "statement", "quarantine", "shift_start", "shift_end", "purchase", "photo", "postmortem_publish"]},
14	    "DEFROST_RULE_TYPES": {"enum": ["runtime_hours", "wall_clock", "temperature"]},
15	    "V34_CHANGE": {"enum": ["absolute_temp", "delta_temp", "unit_change", "scale_change", "none"]},
16	    "PROTOCOL_LABELS": {"enum": ["STATUS", "DOOR", "TRIP", "LOCKOUT", "DEFROST", "HEATER", "BOOT", "SETPOINT", "QUEUE_OVERFLOW"]},
17	    "STATUS_WORDS": {"enum": ["AIR_TEMP", "COIL_TEMP", "DISCH_PRESSURE", "STATE_FLAGS"]},
18	    "FLAG_LABELS": {"enum": ["RUN", "DEFROST", "LOCKOUT", "RECOVERY", "DOOR_OPEN", "ABS_TEMP"]},
19	    "HELDOUT_EVENTS": {"enum": ["AIR_TEMP", "COIL_TEMP", "DISCH_PRESSURE", "STATE_FLAGS", "DOOR", "TRIP", "LOCKOUT", "DEFROST", "HEATER", "FIRMWARE", "SETPOINT", "QUEUE", "RUN", "IDLE", "RECOVERY"]},
20	    "FINDING_STATUS": {"enum": ["established", "probable", "undetermined", "refuted"]},
21	    "CHANNELS": {"enum": ["badge", "exif", "cctv", "forklift", "chat", "tickets", "git", "submeter", "gateway", "probe"]},
22	    "param_estimate": {
23	      "type": "object", "additionalProperties": false,
24	      "required": ["value", "confidence"],
25	      "properties": {
26	        "value": {"type": ["number", "null"]},
27	        "confidence": {"$ref": "#/$defs/conf"},
28	        "note": {"type": "string"}
29	      }
30	    }
31	  },
32	  "properties": {
33	    "schema_version": {"const": "2"},
34	    "mechanism": {
35	      "type": "object", "additionalProperties": false,
36	      "properties": {
37	        "parameters": {"type": "object", "additionalProperties": {"$ref": "#/$defs/param_estimate"}},
38	        "rules": {
39	          "type": "object", "additionalProperties": false,
40	          "properties": {
41	            "defrost_rule_type": {"$ref": "#/$defs/DEFROST_RULE_TYPES"},
42	            "stagger_order": {"type": "array", "items": {"$ref": "#/$defs/zone"}},
43	            "adjacency_pairs": {"type": "array", "items": {"type": "array", "minItems": 2, "maxItems": 2, "items": {"$ref": "#/$defs/zone"}}}
44	          }
45	        }
46	      }
47	    },
48	    "protocol": {
49	      "type": "object", "additionalProperties": false,
50	      "properties": {
51	        "types": {"type": "object", "propertyNames": {"$ref": "#/$defs/hex8"}, "additionalProperties": {"$ref": "#/$defs/PROTOCOL_LABELS"}},
52	        "status_words": {"type": "array", "minItems": 4, "maxItems": 4, "items": {"$ref": "#/$defs/STATUS_WORDS"}},
53	        "temp_scale": {"type": "integer"},
54	        "temp_offset": {"type": "integer"},
55	        "press_scale": {"type": "integer"},
56	        "flag_bits": {"type": "object", "propertyNames": {"$ref": "#/$defs/FLAG_LABELS"}, "additionalProperties": {"type": "integer", "minimum": 0, "maximum": 15}},
57	        "v34_change": {"$ref": "#/$defs/V34_CHANGE"},
58	        "heldout": {"type": "array", "items": {
59	          "type": "object", "additionalProperties": false,
60	          "required": ["seq", "event", "zone"],
61	          "properties": {
62	            "seq": {"type": "integer"},
63	            "ts": {"oneOf": [{"$ref": "#/$defs/iso"}, {"type": "null"}]},
64	            "zone": {"$ref": "#/$defs/zone"},
65	            "event": {"$ref": "#/$defs/HELDOUT_EVENTS"},
66	            "value": {"type": ["number", "null"]}
67	          }}}
68	      }
69	    },
70	    "findings": {
71	      "type": "array",
72	      "items": {
73	        "type": "object", "additionalProperties": false,
74	        "required": ["claim", "status", "confidence", "evidence"],
75	        "properties": {
76	          "claim": {"type": "string", "minLength": 15},
77	          "status": {"$ref": "#/$defs/FINDING_STATUS"},
78	          "confidence": {"$ref": "#/$defs/conf"},
79	          "evidence": {"type": "array", "items": {"type": "string"}},
80	          "alternatives": {"type": "array", "items": {"type": "string"}}
81	        },
82	        "if": {"properties": {"status": {"const": "undetermined"}}},
83	        "then": {"required": ["alternatives"]}
84	      }
85	    },
86	    "timeline": {
87	      "type": "object", "additionalProperties": false,
88	      "properties": {
89	        "events": {"type": "array", "items": {
90	          "type": "object", "additionalProperties": false,
91	          "required": ["actor", "action", "t"],
92	          "properties": {
93	            "actor": {"$ref": "#/$defs/id"},
94	            "action": {"$ref": "#/$defs/ACTIONS"},
95	            "t": {"$ref": "#/$defs/iso"},
96	            "ref": {"type": "string"}
97	          }}},
98	        "clock_offsets_min": {"type": "object", "propertyNames": {"$ref": "#/$defs/CHANNELS"}, "additionalProperties": {"type": "number"}},
99	        "false_claims": {"type": "array", "items": {
100	          "type": "object", "additionalProperties": false,
101	          "required": ["doc_id", "quote"],
102	          "properties": {"doc_id": {"$ref": "#/$defs/id"}, "quote": {"type": "string", "minLength": 8}}}}
103	      }
104	    },
105	    "confidence": {
106	      "type": "object", "additionalProperties": false,
107	      "properties": {"mechanism": {"$ref": "#/$defs/conf"}, "protocol": {"$ref": "#/$defs/conf"},
108	                     "findings": {"$ref": "#/$defs/conf"}, "timeline": {"$ref": "#/$defs/conf"}}
109	    }
110	  }
111	}

