{"cmd":"cat > /work/analyze.py <<'PY'
import sqlite3
for name in ['ledger','queue']:
 c=sqlite3.connect('/work/'+name+'.db')
 c.executescript(open('/evidence/db/'+name+'.sql').read());c.close()
c=sqlite3.connect('/work/ledger.db');c.row_factory=sqlite3.Row
for q in ["select count(*) n,min(recv),max(recv) from readings","select zone,count(*) n,min(recv),max(recv) from readings group by zone","select * from audit","select count(*) n from moves","select count(*) n from lots"]:
 print('\n',q)
 for r in c.execute(q):print(dict(r))
PY
python /work/analyze.py","timeout_s":60}

